CREATE TABLE `tanaman` (
  `id` int NOT NULL,
  `nama` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_latin` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kategori` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Tanaman Hias',
  `ringkasan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deskripsi` text COLLATE utf8mb4_unicode_ci,
  `karakteristik` text COLLATE utf8mb4_unicode_ci,
  `jenis` text COLLATE utf8mb4_unicode_ci,
  `manfaat` text COLLATE utf8mb4_unicode_ci,
  `perawatan` text COLLATE utf8mb4_unicode_ci,
  `foto` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

