INSERT INTO `tanaman` (`id`, `nama`, `nama_latin`, `kategori`, `ringkasan`, `deskripsi`, `karakteristik`, `jenis`, `manfaat`, `perawatan`, `foto`, `video`, `video_url`, `created_at`) VALUES
(1, 'Monstera', 'Monstera deliciosa', 'Tanaman Hias', 'Tanaman hias daun berlubang yang populer.', 'Monstera berasal dari hutan tropis Amerika Tengah. Daunnya besar, mengkilap, dan berlubang khas.', NULL, NULL, NULL, 'Cahaya terang tidak langsung. Siram saat 2-3 cm tanah atas kering. Pupuk sebulan sekali.', 'e89adc74bc1cc19a.jpg', NULL, NULL, '2026-09-29 12:40:07'),
(2, 'Lidah Mertua', 'Sansevieria trifasciata', 'Tanaman Hias', 'Tangguh, cocok untuk pemula.', 'Lidah mertua tahan kondisi kering dan minim cahaya, serta dikenal membantu menyaring udara dalam ruangan.', NULL, NULL, NULL, 'Siram 2 minggu sekali. Hindari genangan air. Tahan cahaya rendah.', '7465c525f611d6fe.jpeg', NULL, NULL, '2026-09-29 12:40:07'),
(3, 'Aglaonema', 'Aglaonema spp.', 'Tanaman Hias', 'Daun berwarna cantik untuk dalam ruangan.', 'Tanaman hias dengan daun hijau, merah, atau bercorak. Bentuknya kompak dan tahan di tempat kurang cahaya.', 'Karakteristik: Tanaman herba dengan daun lebar berbentuk oval atau lanset. Warna daunnya sangat beragam, mulai dari hijau polos hingga kombinasi hijau, putih, merah, dan merah muda.\r\n\r\nAsal Usul: Aglaonema berasal dari Asia tropis, terutama wilayah Asia Tenggara dan sekitarnya.', '', 'Sebagai penghias dalam ruangan dan membantu menyegarkan udara.', 'Suka tempat teduh atau cahaya tidak langsung. Disiram setelah media agak kering dan jangan sampai tergenang.', '5b011276b0715ad7.jpg', NULL, '', '2026-10-07 10:47:08'),
(4, 'Kitolod', 'Hippobroma longiflora', 'Tanaman Obat', 'Tanaman kecil yang tumbuh rendah, tingginya sekitar 20–30 cm.', 'Tanaman kecil yang tumbuh rendah, tingginya sekitar 20–30 cm. Daunnya bergerigi dan bunganya putih berbentuk bintang. Getahnya beracun jika tertelan.', 'Karakteristik:\r\nKitolod merupakan tanaman herba yang dapat tumbuh liar di tempat yang lembap dan cukup teduh. Tanaman ini memiliki daun berwarna hijau berbentuk memanjang dengan tepi bergerigi. Bunganya berwarna putih dan berbentuk seperti bintang dengan lima bagian mahkota. Batangnya bergetah putih dan dapat tumbuh hingga sekitar 1 meter. Tanaman ini sering ditemukan di sekitar halaman, kebun, pinggir jalan, atau area yang tidak terlalu kering.\r\n\r\nAsal Usul:\r\nKitolod (Isotoma longiflora) berasal dari wilayah Amerika tropis, terutama kawasan Karibia dan Amerika Tengah. Tanaman ini kemudian menyebar ke berbagai daerah tropis dan subtropis, termasuk Indonesia. Di Indonesia, Kitolod cukup mudah ditemukan dan sering tumbuh secara alami di lingkungan sekitar rumah maupun kebun.', '', 'Secara tradisional digunakan untuk meredakan mata yang sakit, batuk, dan sesak napas. Sebaiknya hanya untuk pemakaian luar atau dengan arahan ahli, karena mengandung zat yang berbahaya jika berlebihan.', 'Suka tempat terang sampai agak teduh dengan tanah yang gembur dan lembap. Disiram 2–3 kali seminggu. Mudah tumbuh sendiri dan dapat ditanam dari biji.', '6f908fa12ce239ef.jpg', NULL, '', '2026-10-07 10:47:08'),
(5, 'Daun saga', 'Abrus precatorius', 'Tanaman Obat', 'Tanaman merambat dengan daun kecil-kecil.', 'Tanaman merambat dengan daun kecil-kecil. Buahnya berupa polong berisi biji merah-hitam yang sangat beracun.', 'Karakteristik:\r\nDaun saga berasal dari tanaman merambat yang memiliki batang ramping dan dapat menjalar pada tanaman atau benda di sekitarnya. Daunnya berbentuk majemuk dengan banyak anak daun kecil yang tersusun berpasangan. Anak daunnya berbentuk oval hingga lonjong, berwarna hijau, dan memiliki permukaan yang halus. Tanaman ini juga memiliki bunga kecil berwarna merah muda hingga keunguan serta buah berbentuk polong yang berisi biji berwarna merah cerah dengan bagian berwarna hitam.\r\n\r\nAsal Usul:\r\nTanaman saga (Abrus precatorius) berasal dari wilayah Asia Selatan dan Asia Tenggara, kemudian menyebar luas ke berbagai daerah tropis di dunia. Di Indonesia, tanaman ini dapat ditemukan di berbagai daerah dan sering tumbuh liar di semak-semak, kebun, maupun sekitar pepohonan.', '', 'Daunnya secara tradisional direbus atau dikunyah untuk meredakan sariawan, sakit tenggorokan, dan batuk. Bijinya tidak boleh dikonsumsi karena beracun.', 'Perlu sinar matahari penuh dan tanah yang tidak menggenang. Disiram secukupnya dan diberi tiang untuk merambat. Jauhkan bijinya dari anak-anak.', '89063749c73960a2.jpg', NULL, '', '2026-10-07 10:47:08'),
(6, 'Daun kelor', 'Moringa oleifera', 'Tanaman Obat', 'Pohon berukuran sedang dengan daun kecil berwarna hijau, bunga putih kekuningan, dan buah berbentuk polong panjang.', 'Pohon berukuran sedang dengan daun kecil berwarna hijau, bunga putih kekuningan, dan buah berbentuk polong panjang.', 'Karakteristik:\r\nDaun kelor berasal dari tanaman berbentuk pohon kecil yang dapat tumbuh sekitar 5–10 meter. Daunnya berwarna hijau dan berbentuk majemuk, dengan banyak anak daun berukuran kecil dan berbentuk bulat hingga oval. Tanaman kelor memiliki bunga berwarna putih kekuningan dan buah berbentuk panjang seperti polong. Kelor dikenal sebagai tanaman yang mudah tumbuh dan dapat beradaptasi dengan kondisi lingkungan yang cukup kering.\r\n\r\nAsal Usul:\r\nTanaman kelor (Moringa oleifera) berasal dari India bagian utara, khususnya wilayah sekitar kaki Pegunungan Himalaya. Tanaman ini kemudian menyebar ke berbagai wilayah tropis dan subtropis, termasuk Indonesia. Di Indonesia, kelor banyak ditanam di pekarangan rumah, kebun, dan daerah pedesaan.', '', 'Kaya protein, vitamin, kalsium, dan zat besi. Membantu menjaga daya tahan tubuh, melancarkan ASI, dan menjaga kadar gula darah.', 'Perlu sinar matahari penuh dan tanah yang tidak tergenang. Tahan kekeringan. Dapat ditanam dari potongan batang atau biji, dan sebaiknya dipangkas agar mudah dipetik.', '10a88678e0496bb3.jpg', NULL, '', '2026-10-07 10:47:08'),
(7, 'Cocor bebek', 'Kalanchoe pinnata', 'Tanaman Obat', 'Tanaman berdaun tebal dan berair dengan tepi bergerigi.', 'Tanaman berdaun tebal dan berair dengan tepi bergerigi. Tunas baru tumbuh dari tepi daunnya.', 'Karakteristik:\r\nCocor bebek merupakan tanaman sukulen yang memiliki batang tegak dan daun tebal, berdaging, serta berwarna hijau. Daunnya berbentuk oval hingga lonjong dengan tepi bergerigi. Salah satu ciri khasnya adalah tunas kecil dapat tumbuh di sepanjang tepi daun, kemudian jatuh dan berkembang menjadi tanaman baru. Bunganya berbentuk lonceng dan biasanya berwarna merah muda, merah, atau jingga.\r\n\r\nAsal Usul:\r\nCocor bebek berasal dari Madagaskar, sebuah pulau di lepas pantai Afrika bagian timur. Tanaman ini kemudian menyebar ke berbagai wilayah tropis, termasuk Indonesia, karena mudah diperbanyak dan mampu beradaptasi dengan lingkungan yang hangat. Di Indonesia, cocor bebek sering ditanam sebagai tanaman hias maupun tanaman yang digunakan dalam pengobatan tradisional.', '', 'Daunnya secara tradisional ditempelkan atau diremas untuk meredakan bisul, luka ringan, demam, dan sakit kepala.', 'Suka tempat terang dengan tanah berpasir yang cepat kering. Cukup disiram sedikit, sekitar seminggu sekali. Mudah tumbuh dari daun yang jatuh.', '2b0ec9e469d73927.jpg', NULL, '', '2026-10-07 10:47:08'),
(8, 'Kunyit kuning', 'Curcuma longa', 'Tanaman Obat', 'Tanaman setinggi sekitar 1 m dengan daun lebar.', 'Tanaman setinggi sekitar 1 m dengan daun lebar. Umbi akarnya berwarna kuning-oranye dan berbau khas.', 'Karakteristik:\r\nKunyit merupakan tanaman herba yang memiliki daun berwarna hijau, berbentuk lonjong dan memanjang. Bagian yang paling dikenal adalah rimpangnya yang berada di dalam tanah dan memiliki warna kuning hingga jingga dengan aroma khas. Batang kunyit sebenarnya merupakan batang semu yang terbentuk dari pelepah daun. Tanaman ini dapat tumbuh sekitar 1 meter dan memiliki bunga berwarna putih hingga kekuningan.\r\n\r\nAsal Usul:\r\nKunyit (Curcuma longa) berasal dari Asia Selatan dan Asia Tenggara, terutama wilayah India. Tanaman ini telah lama dibudidayakan dan digunakan di berbagai negara Asia sebagai bumbu masakan, pewarna alami, serta dalam pengobatan tradisional. Kunyit kemudian menyebar dan banyak dibudidayakan di Indonesia.', '', 'Membantu melancarkan pencernaan, meredakan nyeri haid, dan menjaga kesehatan hati. Juga digunakan sebagai bumbu dan pewarna makanan alami.', 'Cocok di tempat setengah teduh dengan tanah gembur yang subur. Disiram teratur tanpa menggenang. Dapat dipanen sekitar umur 8–10 bulan.', 'fd2638b8712051b3.jpg', NULL, '', '2026-10-07 10:47:08'),
(9, 'Kunyit putih', 'Curcuma zedoaria', 'Tanaman Obat', 'Umbi akarnya berwarna putih kekuningan dengan aroma seperti mangga mentah.', 'Umbi akarnya berwarna putih kekuningan dengan aroma seperti mangga mentah. Daunnya lebar dengan garis ungu di tengah.', 'Karakteristik:\r\nKunyit putih merupakan tanaman herba yang memiliki daun berwarna hijau dengan bentuk memanjang dan cukup lebar. Tanaman ini memiliki rimpang yang tumbuh di dalam tanah dengan bagian dalam berwarna putih hingga kekuningan serta memiliki aroma yang khas. Batangnya berupa batang semu yang terbentuk dari pelepah daun. Bunganya dapat berwarna putih dengan sedikit warna ungu atau merah muda.\r\n\r\nAsal Usul:\r\nKunyit putih (Curcuma zedoaria) berasal dari Asia Selatan dan Asia Tenggara. Tanaman ini kemudian menyebar ke berbagai wilayah tropis, termasuk Indonesia. Di Indonesia, kunyit putih banyak ditemukan dan dibudidayakan sebagai tanaman obat tradisional serta dimanfaatkan dalam berbagai keperluan herbal.', '', 'Secara tradisional digunakan untuk meredakan perut kembung dan gangguan pencernaan serta menjaga stamina. Ibu hamil sebaiknya berkonsultasi dahulu.', 'Suka tempat agak teduh dengan tanah subur, gembur, dan lembap. Ditanam dari potongan umbi yang sudah bertunas.', '4ac853d87d221837.jpg', NULL, '', '2026-10-07 10:47:08'),
(10, 'Bangun-bangun', 'Plectranthus amboinicus', 'Tanaman Obat', 'Tanaman berbatang lunak dengan daun tebal berbulu halus, berbau tajam, dan tepi daun bergerigi.', 'Tanaman berbatang lunak dengan daun tebal berbulu halus, berbau tajam, dan tepi daun bergerigi.', 'Karakteristik: Tanaman herba dengan batang agak berdaging. Daunnya tebal, berbentuk bulat telur, permukaannya berbulu dan memiliki aroma yang kuat ketika diremas. Tumbuh membentuk semak kecil.\r\n\r\nAsal Usul: Bangun-bangun (Coleus/Plectranthus amboinicus) berasal dari kawasan Afrika Selatan dan wilayah tropis sekitarnya, kemudian menyebar dan dibudidayakan di Asia termasuk Indonesia.', '', 'Dikenal dapat melancarkan ASI serta meredakan batuk, pilek, demam, dan masuk angin. Sering dimasak sebagai sayur bening atau pepes.', 'Suka tempat terang sampai agak teduh dengan tanah gembur. Disiram 2 kali seminggu. Mudah ditanam dari potongan batang.', 'd7ca721e50f196c7.jpg', NULL, '', '2026-10-07 10:47:08'),
(11, 'Bawang dayak', 'Eleutherine bulbosa', 'Tanaman Obat', 'Tanaman berdaun panjang seperti pedang dengan umbi merah tua mirip bawang merah kecil dan bunga putih.', 'Tanaman berdaun panjang seperti pedang dengan umbi merah tua mirip bawang merah kecil dan bunga putih.', 'Karakteristik: Tanaman herba berumbi dengan daun panjang dan sempit berwarna hijau. Umbinya berbentuk menyerupai bawang merah dan memiliki warna merah keunguan.\r\n\r\nAsal Usul: Bawang dayak (Eleutherine bulbosa) berasal dari Amerika tropis dan kemudian dibudidayakan di berbagai daerah, termasuk Kalimantan dan wilayah Indonesia lainnya.', '', 'Umbinya diolah menjadi teh atau ramuan untuk membantu menjaga kadar kolesterol dan gula darah serta melawan kuman.', 'Suka tempat agak teduh dengan tanah gembur dan lembap. Ditanam dari umbi atau anakan. Umbi dapat dipanen pada umur 3–4 bulan.', '019d600044a486a7.jpg', NULL, '', '2026-10-07 10:47:08'),
(12, 'Patah tulang', 'Euphorbia tirucalli', 'Tanaman Obat', 'Tanaman perdu dengan cabang ramping seperti pensil hijau dan hampir tanpa daun.', 'Tanaman perdu dengan cabang ramping seperti pensil hijau dan hampir tanpa daun. Getahnya putih dan sangat perih jika terkena kulit atau mata.', 'Karakteristik: Tanaman berupa semak atau pohon kecil dengan banyak cabang berbentuk seperti ranting tanpa banyak daun. Batangnya berwarna hijau dan mengeluarkan getah putih jika dipatahkan.\r\n\r\nAsal Usul: Patah tulang (Euphorbia tirucalli) berasal dari Afrika tropis, kemudian menyebar ke berbagai wilayah tropis dan banyak ditanam di Indonesia.', '', 'Secara tradisional dibalurkan pada bagian luar tubuh untuk membantu pemulihan keseleo dan nyeri sendi. Tidak boleh diminum karena getahnya beracun.', 'Perlu sinar matahari penuh dan tanah berpasir. Hampir tidak perlu disiram. Gunakan sarung tangan saat memangkas karena getahnya berbahaya.', '870a1e4d05fc089d.jpg', NULL, '', '2026-10-07 10:47:08'),
(13, 'Daun sirih / sirih hijau', 'Piper betle', 'Tanaman Obat', 'Tanaman merambat dengan daun hijau berbentuk jantung.', 'Tanaman merambat dengan daun hijau berbentuk jantung. Rasa dan aromanya khas dan agak tajam.', 'Karakteristik: Tanaman merambat dengan batang beruas dan memiliki akar pelekat. Daunnya berbentuk hati, berwarna hijau, mengilap, serta memiliki aroma khas ketika diremas.\r\n\r\nAsal Usul: Sirih (Piper betle) berasal dari Asia Selatan hingga Asia Tenggara dan telah lama dibudidayakan di Indonesia.', '', 'Air rebusannya digunakan untuk mengatasi bau mulut, keputihan, mimisan, gatal, dan mata merah. Juga dapat membersihkan luka ringan.', 'Suka tempat agak teduh dengan tanah lembap dan subur. Perlu tiang untuk merambat dan disiram teratur.', 'c2934f15d42f3c85.jpg', NULL, '', '2026-10-07 10:47:08'),
(14, 'Kencur', 'Kaempferia galanga', 'Tanaman Obat', 'Tanaman pendek dengan daun lebar yang menempel di tanah.', 'Tanaman pendek dengan daun lebar yang menempel di tanah. Umbi akarnya berwarna cokelat muda dan harum.', 'Karakteristik: Tanaman herba berukuran rendah dengan daun lebar dan pendek yang tumbuh dekat permukaan tanah. Rimpangnya kecil, berwarna cokelat muda di bagian luar dan putih kekuningan di dalam serta memiliki aroma khas.\r\n\r\nAsal Usul: Kencur (Kaempferia galanga) berasal dari Asia Selatan dan Asia Tenggara, dan telah lama dibudidayakan di Indonesia.', '', 'Digunakan dalam jamu beras kencur untuk meredakan batuk dan perut kembung, menambah nafsu makan, serta mengurangi pegal-pegal.', 'Suka tempat agak teduh dengan tanah gembur dan lembap. Dapat ditanam di polybag dan dipanen pada umur 6–8 bulan.', 'd91f7eb93bf68b12.jpg', NULL, '', '2026-10-07 10:47:08'),
(15, 'Bangle', 'Zingiber purpureum', 'Tanaman Obat', 'Umbi akarnya besar, berwarna kuning pucat, berbau tajam, dan rasanya pahit-pedas.', 'Umbi akarnya besar, berwarna kuning pucat, berbau tajam, dan rasanya pahit-pedas. Daunnya panjang dan runcing.', 'Karakteristik: Tanaman herba berumpun dengan daun panjang dan tegak. Memiliki rimpang yang berwarna kekuningan dan beraroma khas. Bunganya tumbuh dari bagian tengah rumpun.\r\n\r\nAsal Usul: Bangle (Zingiber montanum) berasal dari Asia tropis, terutama kawasan Asia Tenggara, dan banyak ditemukan serta dibudidayakan di Indonesia.', '', 'Secara tradisional digunakan untuk membantu menurunkan berat badan, melancarkan buang air besar, dan meredakan nyeri sendi. Tidak dianjurkan bagi ibu hamil.', 'Cocok di tempat agak teduh sampai terang dengan tanah subur dan gembur. Disiram teratur. Dapat dipanen sekitar umur 9–12 bulan.', 'fe24a71b7e784369.jpg', NULL, '', '2026-10-07 10:47:08'),
(16, 'Sereh', 'Cymbopogon citratus', 'Tanaman Obat', 'Tanaman berumpun seperti rumput, tingginya 1–1,5 m.', 'Tanaman berumpun seperti rumput, tingginya 1–1,5 m. Batangnya berbau segar seperti lemon.', 'Karakteristik: Tanaman rumput yang tumbuh berumpun dengan daun panjang, sempit, dan tajam. Batangnya membentuk pangkal yang tebal dan mengeluarkan aroma lemon yang kuat ketika diremas.\r\n\r\nAsal Usul: Sereh atau serai (Cymbopogon citratus) berasal dari India dan Sri Lanka dan kemudian menyebar luas di daerah tropis, termasuk Indonesia.', '', 'Meredakan masuk angin dan perut kembung, penyedap masakan dan minuman hangat, serta dapat mengusir nyamuk.', 'Perlu sinar matahari penuh dan tanah yang tidak tergenang. Dapat diperbanyak dengan memisahkan rumpunnya.', '7dd6937f16029aef.jpg', NULL, '', '2026-10-07 10:47:08'),
(17, 'Lidah buaya', 'Aloe vera', 'Tanaman Obat', 'Tanaman berdaun tebal berdaging yang tersusun melingkar.', 'Tanaman berdaun tebal berdaging yang tersusun melingkar. Di dalam daunnya terdapat gel bening, dan tepinya sedikit berduri.', 'Karakteristik: Tanaman sukulen dengan daun tebal, panjang, berdaging, dan memiliki tepi bergerigi kecil. Bagian dalam daunnya mengandung gel bening.\r\n\r\nAsal Usul: Lidah buaya (Aloe vera) berasal dari wilayah Semenanjung Arab, kemudian menyebar dan dibudidayakan di berbagai daerah tropis dan subtropis.', '', 'Gelnya digunakan untuk merawat luka bakar ringan, kulit, dan rambut, serta dapat dibuat minuman. Getah kuning di kulit daun dapat memicu mencret, jadi hindari berlebihan.', 'Suka tempat terang sampai terkena matahari penuh. Gunakan tanah berpasir dan siram setelah tanah kering, sekitar 1–2 minggu sekali.', '1c13898047117b7c.jpg', NULL, '', '2026-10-07 10:47:08'),
(18, 'Kumis kucing', 'Orthosiphon aristatus', 'Tanaman Obat', 'Tanaman tegak berdaun oval bergerigi dengan bunga ungu atau putih.', 'Tanaman tegak berdaun oval bergerigi dengan bunga ungu atau putih. Benang sarinya panjang seperti kumis kucing.', 'Karakteristik: Tanaman herba dengan batang tegak dan daun berbentuk oval dengan tepi bergerigi. Bunganya berwarna putih atau ungu dengan benang sari panjang yang menjulur keluar seperti kumis kucing.\r\n\r\nAsal Usul: Kumis kucing (Orthosiphon aristatus) berasal dari Asia Tenggara dan Australia bagian utara, dan banyak tumbuh serta dibudidayakan di Indonesia.', '', 'Teh daunnya membantu memperlancar buang air kecil. Secara tradisional digunakan untuk batu ginjal, infeksi saluran kemih, dan tekanan darah tinggi.', 'Suka tempat cukup terang sampai agak teduh dengan tanah gembur dan lembap. Mudah ditanam dari potongan batang.', 'c679bfc0a22d3709.jpg', NULL, '', '2026-10-07 10:47:08'),
(19, 'Binahong', 'Anredera cordifolia', 'Tanaman Obat', 'Tanaman merambat dengan daun tebal berbentuk jantung dan bunga kecil putih yang harum.', 'Tanaman merambat dengan daun tebal berbentuk jantung dan bunga kecil putih yang harum. Umbi kecil tumbuh di sela daunnya.', 'Karakteristik: Tanaman merambat dengan batang lunak. Daunnya berbentuk hati, tebal, berdaging, dan berwarna hijau. Tanaman ini dapat tumbuh dengan cepat dan merambat pada penyangga.\r\n\r\nAsal Usul: Binahong (Anredera cordifolia) berasal dari Amerika Selatan, kemudian menyebar ke berbagai wilayah tropis termasuk Indonesia.', '', 'Daunnya dikenal dapat mempercepat penyembuhan luka, membantu mengatasi maag dan diabetes, serta menjaga stamina. Dapat dimakan sebagai lalapan atau direbus.', 'Cocok di tempat cukup terang sampai agak teduh dengan tanah gembur. Disiram teratur dan diberi tiang untuk merambat.', '159b52026b911110.jpg', NULL, '', '2026-10-07 10:47:08'),
(20, 'Tanaman jahe', 'Zingiber officinale', 'Tanaman Obat', 'Tanaman tegak setinggi 60–100 cm dengan daun sempit.', 'Tanaman tegak setinggi 60–100 cm dengan daun sempit. Umbi akarnya berwarna krem, rasanya pedas dan menghangatkan.', 'Karakteristik: Tanaman herba berumpun dengan batang semu yang terbentuk dari pelepah daun. Daunnya panjang dan sempit, sedangkan rimpangnya bercabang dan memiliki aroma serta rasa pedas khas.\r\n\r\nAsal Usul: Jahe (Zingiber officinale) berasal dari Asia Tenggara, kemudian menyebar dan dibudidayakan di berbagai wilayah tropis.', '', 'Menghangatkan badan, meredakan mual dan masuk angin, mengurangi nyeri otot, serta melancarkan pencernaan. Digunakan sebagai bumbu dan wedang.', 'Suka tempat agak teduh dengan tanah subur dan gembur. Disiram teratur tanpa menggenang. Dapat dipanen pada umur 8–10 bulan.', 'bdc5c652edc34c78.jpg', NULL, '', '2026-10-07 10:47:08'),
(21, 'Dandang gendis', 'Clinacanthus nutans', 'Tanaman Obat', 'Tanaman perdu dengan daun sempit berwarna hijau tua mengilap dan batang ramping yang menjuntai.', 'Tanaman perdu dengan daun sempit berwarna hijau tua mengilap dan batang ramping yang menjuntai.', 'Karakteristik: Tanaman berupa semak dengan batang bercabang. Daunnya berwarna hijau, berbentuk lonjong hingga lanset dan tersusun berhadapan. Bunganya berwarna putih dengan bentuk memanjang.\r\n\r\nAsal Usul: Dandang gendis (Clinacanthus nutans) berasal dari Asia Tenggara, termasuk Indonesia, Malaysia, Thailand, dan wilayah sekitarnya.', '', 'Daunnya secara tradisional diseduh atau ditempelkan pada kulit untuk membantu meredakan radang, herpes, luka bakar, dan diabetes.', 'Suka tempat terang sampai agak teduh dengan tanah gembur dan lembap. Mudah ditanam dari potongan batang.', 'afdbba838c6c13c7.jpg', NULL, '', '2026-10-07 10:47:08'),
(22, 'Temulawak', 'Curcuma zanthorrhiza', 'Tanaman Obat', 'Tanaman tegak setinggi 1–2 m.', 'Tanaman tegak setinggi 1–2 m. Umbi akarnya berwarna kuning jingga, rasanya pahit, dan daunnya lebar dengan garis ungu.', 'Karakteristik:\r\nTemulawak merupakan tanaman herba berumpun dengan daun panjang dan lebar yang tumbuh dari batang semu. Bagian yang paling banyak dimanfaatkan adalah rimpangnya, yang memiliki warna kuning hingga jingga dan aroma khas. Tanaman ini dapat tumbuh hingga sekitar 2 meter.\r\n\r\nAsal Usul:\r\nTemulawak berasal dari Indonesia, terutama wilayah Pulau Jawa dan beberapa pulau di sekitarnya. Tanaman ini kemudian dibudidayakan di berbagai wilayah tropis dan dikenal sebagai salah satu tanaman obat tradisional Indonesia.', '', 'Dikenal dapat menjaga kesehatan hati, menambah nafsu makan, dan melancarkan pencernaan. Banyak digunakan sebagai bahan jamu.', 'Suka tempat agak teduh dengan tanah gembur yang banyak bahan organik. Disiram teratur. Dapat dipanen pada umur 9–12 bulan.', '17b6d1bf780ff290.jpg', NULL, '', '2026-10-07 10:47:08'),
(23, 'Pegagan', 'Centella asiatica', 'Tanaman Obat', 'Tanaman yang menjalar di tanah dengan daun bulat berlekuk berwarna hijau segar.', 'Tanaman yang menjalar di tanah dengan daun bulat berlekuk berwarna hijau segar.', 'Karakteristik:\r\nPegagan merupakan tanaman herba yang tumbuh menjalar di permukaan tanah. Daunnya berbentuk seperti ginjal atau kipas dengan tepi agak bergerigi dan berwarna hijau. Batangnya tipis dan memiliki akar pada bagian ruasnya, sehingga tanaman dapat menyebar dengan cepat.\r\n\r\nAsal Usul:\r\nPegagan berasal dari wilayah Asia, Australia, dan kepulauan Pasifik dan telah lama tumbuh di daerah tropis. Di Indonesia, tanaman ini banyak ditemukan di tempat yang lembap seperti kebun, halaman, dan area berumput.', '', 'Membantu menyembuhkan luka, melancarkan peredaran darah, menjaga daya ingat, dan menenangkan. Dapat dimakan sebagai lalapan atau diseduh menjadi teh.', 'Suka tempat agak teduh dengan tanah lembap dan tidak tahan kering. Mudah ditanam dari sulur yang menjalar.', '804fef4674032bf1.jpg', NULL, '', '2026-10-07 10:47:08'),
(24, 'Kemangi', 'Ocimum × africanum', 'Tanaman Obat', 'Tanaman kecil setinggi 30–60 cm dengan daun hijau muda yang wangi dan bunga putih kecil.', 'Tanaman kecil setinggi 30–60 cm dengan daun hijau muda yang wangi dan bunga putih kecil.', 'Karakteristik:\r\nKemangi merupakan tanaman herba yang memiliki batang bercabang dan daun kecil berbentuk oval dengan tepi bergerigi. Daunnya berwarna hijau dan mengeluarkan aroma khas yang kuat ketika diremas. Bunganya berukuran kecil dan tumbuh dalam rangkaian pada ujung batang.\r\n\r\nAsal Usul:\r\nKemangi merupakan tanaman yang banyak ditemukan dan dibudidayakan di wilayah Asia dan Afrika tropis. Tanaman ini telah lama digunakan di Indonesia sebagai lalapan, bumbu masakan, dan tanaman aromatik.', '', 'Digunakan sebagai lalapan dan pelengkap masakan. Membantu pencernaan, mengurangi perut kembung dan bau mulut, serta melancarkan ASI.', 'Perlu sinar matahari penuh dan tanah gembur yang lembap. Bunganya dipangkas agar daun terus tumbuh. Ditanam dari biji.', '00eaffa6924119a6.jpg', NULL, '', '2026-10-07 10:47:08'),
(25, 'Kenanga', 'Cananga odorata', 'Tanaman Hias', 'Pohon tinggi dengan daun lonjong.', 'Pohon tinggi dengan daun lonjong. Bunganya berwarna kuning kehijauan, berbentuk bintang, dan sangat harum.', 'Karakteristik: Pohon kecil hingga sedang dengan daun hijau berbentuk oval. Bunganya memiliki kelopak panjang, tipis, berwarna hijau kekuningan dan mengeluarkan aroma harum yang kuat.\r\n\r\nAsal Usul: Kenanga (Cananga odorata) berasal dari kawasan Asia Tenggara, termasuk Indonesia, dan secara alami tersebar hingga Papua serta Queensland.', '', 'Bunganya digunakan untuk hiasan dan upacara adat, bahan minyak wangi, serta aromaterapi.', 'Perlu sinar matahari penuh dan tanah subur yang lembap. Disiram rutin dan dipangkas agar tidak terlalu tinggi.', '114cb224f0e68205.jpg', NULL, '', '2026-10-07 10:47:08'),
(26, 'Daun pandan / pohon pandan', 'Pandanus amaryllifolius', 'Tanaman Hias', 'Tanaman perdu berumpun dengan daun panjang dan pipih berwarna hijau yang harum.', 'Tanaman perdu berumpun dengan daun panjang dan pipih berwarna hijau yang harum.', 'Karakteristik: Tanaman berdaun panjang, sempit, dan berwarna hijau. Daunnya tersusun rapat dan memiliki aroma khas, terutama pada pandan wangi.\r\n\r\nAsal Usul: Pandan wangi (Pandanus amaryllifolius) berasal dari Asia Tenggara dan banyak dibudidayakan di Indonesia.', '', 'Digunakan sebagai pewangi dan pewarna alami makanan, serta pengharum ruangan.', 'Suka tempat agak teduh dengan tanah gembur dan lembap. Disiram 2–3 kali seminggu. Dapat diperbanyak dengan anakannya.', '7eabe125b20bb23d.jpg', NULL, '', '2026-10-07 10:47:08'),
(27, 'Daun suji', 'Dracaena angustifolia', 'Tanaman Hias', 'Tanaman perdu berumpun dengan daun hijau tua yang panjang dan melengkung.', 'Tanaman perdu berumpun dengan daun hijau tua yang panjang dan melengkung.', 'Karakteristik: Tanaman perdu dengan daun panjang, sempit, tebal, dan berwarna hijau tua. Daunnya tumbuh rapat dan tegak sehingga memberikan tampilan seperti rumpun.\r\n\r\nAsal Usul: Suji (Dracaena angustifolia) berasal dari Asia tropis, terutama kawasan Asia Tenggara, dan banyak ditemukan di Indonesia.', '', 'Sebagai tanaman hias taman, dan daunnya digunakan sebagai pewarna hijau alami serta pewangi kue tradisional.', 'Suka tempat teduh sampai agak teduh dengan tanah gembur dan lembap. Dapat ditanam dari potongan batang.', '0aff74980bd9f36f.jpg', NULL, '', '2026-10-07 10:47:08'),
(28, 'Melati', 'Jasminum sambac', 'Tanaman Hias', 'Tanaman perdu kecil dengan daun hijau mengilap.', 'Tanaman perdu kecil dengan daun hijau mengilap. Bunganya putih kecil dan sangat harum.', 'Karakteristik: Tanaman perdu atau merambat dengan daun hijau dan bunga kecil berwarna putih. Bunganya memiliki aroma harum yang khas.\r\n\r\nAsal Usul: Melati (Jasminum sambac) berasal dari Asia Selatan hingga Asia Tenggara dan telah lama dibudidayakan di Indonesia.', '', 'Sebagai tanaman hias yang harum. Bunganya digunakan untuk teh, minyak wangi, dan rangkaian upacara adat. Melati juga dikenal sebagai bunga nasional Indonesia.', 'Perlu sinar matahari penuh dan tanah subur yang gembur. Disiram rutin dan dipangkas agar banyak berbunga.', 'c33d1a4b7c3041fb.jpg', NULL, '', '2026-10-07 10:47:08'),
(29, 'Bakung', 'Crinum asiaticum', 'Tanaman Hias', 'Tanaman berumbi besar dengan daun lebar seperti pita.', 'Tanaman berumbi besar dengan daun lebar seperti pita. Bunganya putih, berumbai, dan harum pada malam hari.', 'Karakteristik: Tanaman herba berumbi dengan daun panjang, tebal, dan berwarna hijau. Bunganya besar dan biasanya berwarna putih dengan aroma harum.\r\n\r\nAsal Usul: Bakung (Crinum asiaticum) berasal dari wilayah Asia tropis hingga Australia, dan banyak tumbuh di daerah pesisir serta lingkungan tropis.', '', 'Sebagai tanaman hias taman. Daunnya secara tradisional digunakan untuk pemakaian luar pada bengkak dan nyeri sendi. Umbinya beracun jika dimakan.', 'Cocok di tempat setengah teduh sampai terang dengan tanah yang lembap. Tumbuh baik di tepi kolam. Ditanam dari anakan umbi.', '2e2d24ef0f3d70a2.jpg', NULL, '', '2026-10-07 10:47:08'),
(30, 'Bambu Jepang', 'Pseudosasa japonica', 'Tanaman Hias', 'Bambu kecil yang bercabang dengan batang hijau dan daun sempit memanjang yang tumbuh rapat.', 'Bambu kecil yang bercabang dengan batang hijau dan daun sempit memanjang yang tumbuh rapat.', 'Karakteristik: Tanaman berumpun dengan batang ramping dan ruas yang jelas. Daunnya kecil hingga sedang dan tumbuh cukup rapat sehingga membentuk rumpun yang rimbun.\r\n\r\nAsal Usul: Bambu Jepang umumnya merujuk pada beberapa jenis bambu hias, salah satunya Pleioblastus spp., yang berasal dari Asia Timur, terutama Jepang dan wilayah sekitarnya.', '', 'Digunakan sebagai pagar hidup dan peneduh taman, serta mempercantik tampilan taman minimalis.', 'Cocok di tempat terang sampai agak teduh dengan tanah gembur dan subur. Disiram sekitar 3 kali seminggu. Tahan angin.', 'cb323abbb1c6aaa3.jpg', NULL, '', '2026-10-07 10:47:08'),
(31, 'Syngonium wendlandii', 'Syngonium wendlandii', 'Tanaman Hias', 'Tanaman merambat dengan daun berbentuk anak panah berwarna hijau gelap dengan garis putih keperakan.', 'Tanaman merambat dengan daun berbentuk anak panah berwarna hijau gelap dengan garis putih keperakan.', 'Karakteristik: Tanaman merambat dengan daun berbentuk anak panah. Daunnya berwarna hijau tua dengan garis atau bagian tengah berwarna lebih terang hingga keperakan.\r\n\r\nAsal Usul: Syngonium wendlandii berasal dari Amerika Tengah, terutama kawasan Kosta Rika dan sekitarnya.', '', 'Sebagai tanaman hias dalam ruangan, cocok untuk pot gantung atau dirambatkan pada tiang.', 'Suka cahaya terang yang tidak langsung dan media yang gembur dan lembap. Disiram saat permukaan media mulai kering.', 'd1ffb5786eefaa6f.jpg', NULL, '', '2026-10-07 10:47:08'),
(32, 'Kembang sepatu', 'Hibiscus rosa-sinensis', 'Tanaman Hias', 'Tanaman perdu setinggi 1–3 m dengan bunga besar berwarna merah, jingga, kuning, atau merah muda berbentuk terompet.', 'Tanaman perdu setinggi 1–3 m dengan bunga besar berwarna merah, jingga, kuning, atau merah muda berbentuk terompet.', 'Karakteristik: Perdu dengan daun hijau mengilap dan tepi bergerigi. Bunganya besar dengan lima mahkota dan memiliki berbagai warna seperti merah, kuning, merah muda, dan putih.\r\n\r\nAsal Usul: Kembang sepatu (Hibiscus rosa-sinensis) berasal dari Asia tropis, meskipun asal alaminya sulit dipastikan karena telah lama dibudidayakan dan mengalami banyak persilangan.', '', 'Sebagai tanaman hias taman. Bunganya secara tradisional digunakan untuk meredakan demam dan batuk, serta dapat diseduh menjadi teh.', 'Perlu sinar matahari penuh dan tanah subur. Disiram sehari sekali saat cuaca panas, serta dipangkas dan dipupuk secara berkala.', '7862a2de672c14aa.jpg', NULL, '', '2026-10-07 10:47:08'),
(33, 'Keladi', 'Caladium bicolor', 'Tanaman Hias', 'Tanaman berumbi dengan daun lebar berbentuk hati yang bercorak merah muda, putih, dan hijau.', 'Tanaman berumbi dengan daun lebar berbentuk hati yang bercorak merah muda, putih, dan hijau.', 'Karakteristik: Tanaman herba berumbi dengan daun berbentuk hati atau anak panah. Daunnya memiliki berbagai kombinasi warna seperti hijau, putih, merah muda, dan merah.\r\n\r\nAsal Usul: Keladi hias (Caladium spp.) berasal dari Amerika tropis, terutama wilayah Amerika Selatan.', '', 'Sebagai tanaman hias daun. Seluruh bagiannya dapat membuat gatal dan perih, sehingga jangan dimakan.', 'Suka tempat agak teduh dengan tanah gembur dan lembap. Daunnya rontok saat musim kering, lalu tumbuh lagi dari umbinya.', '634610b1f6dae90f.jpg', NULL, '', '2026-10-07 10:47:08'),
(34, 'Kayu urip', 'Gliricidia sepium', 'Tanaman Hias', 'Pohon kecil yang bercabang dengan daun majemuk dan bunga merah muda keunguan.', 'Pohon kecil yang bercabang dengan daun majemuk dan bunga merah muda keunguan. Sering digunakan sebagai pagar hidup.', 'Karakteristik: Nama “kayu urip” dapat digunakan sebagai nama lokal untuk beberapa tanaman berbeda. Karena itu karakteristiknya bergantung pada jenis tanaman yang dimaksud.\r\n\r\nAsal Usul: Asal usulnya juga tidak dapat dipastikan hanya berdasarkan nama “kayu urip”. Kalau kamu kirim foto tanaman Kayu Urip yang kamu punya, aku bisa identifikasi spesiesnya dulu.', '', 'Digunakan sebagai pagar hidup, peneduh, pupuk hijau penyubur tanah, dan pakan ternak. Nama ini dapat berbeda di tiap daerah.', 'Perlu sinar matahari penuh dan tahan kering. Dapat tumbuh di berbagai jenis tanah dan mudah ditanam dari potongan batang.', 'ee691b2579f6d684.jpg', NULL, '', '2026-10-07 10:47:08'),
(35, 'Pucuk merah', 'Syzygium oleana', 'Tanaman Hias', 'Tanaman perdu padat dengan pucuk daun muda berwarna merah mengilap, sedangkan daun tuanya hijau tua.', 'Tanaman perdu padat dengan pucuk daun muda berwarna merah mengilap, sedangkan daun tuanya hijau tua.', 'Karakteristik: Tanaman perdu dengan daun muda berwarna merah atau merah-oranye yang kemudian berubah menjadi hijau setelah tua. Daunnya berbentuk lonjong dan tumbuh rapat pada percabangan.\r\n\r\nAsal Usul: Pucuk merah (Syzygium myrtifolium) berasal dari Asia Tenggara, termasuk wilayah Indonesia dan sekitarnya.', '', 'Sebagai pagar hidup dan penghias taman, serta membantu menyerap debu.', 'Perlu sinar matahari penuh dan tanah gembur. Disiram teratur dan dipangkas agar berbentuk pagar atau bulat.', '4b373d4a6a6b1902.jpg', NULL, '', '2026-10-07 10:47:08'),
(36, 'Mangkokan', 'Polyscias scutellaria', 'Tanaman Hias', 'Tanaman perdu dengan daun bulat dan tebal seperti mangkuk, berwarna hijau mengilap atau belang putih.', 'Tanaman perdu dengan daun bulat dan tebal seperti mangkuk, berwarna hijau mengilap atau belang putih.', 'Karakteristik: Tanaman perdu dengan daun berbentuk seperti mangkuk atau cekungan, berwarna hijau dan memiliki aroma khas. Daunnya relatif tebal dan tumbuh pada batang yang bercabang.\r\n\r\nAsal Usul: Mangkokan (Polyscias scutellaria) berasal dari wilayah Asia tropis dan Kepulauan Pasifik dan banyak dibudidayakan di Indonesia.', '', 'Sebagai tanaman pagar dan hias. Daunnya secara tradisional digunakan untuk melancarkan ASI dan meredakan demam ringan.', 'Suka tempat terang sampai agak teduh dengan tanah gembur dan lembap. Mudah ditanam dari potongan batang.', '7304aa66c3d70bcc.jpg', NULL, '', '2026-10-07 10:47:08'),
(37, 'Bunga Asoka', 'Ixora coccinea', 'Tanaman Hias', 'Tanaman perdu dengan bunga bergerombol berwarna merah, jingga, atau kuning, serta daun hijau tua yang mengilap.', 'Tanaman perdu dengan bunga bergerombol berwarna merah, jingga, atau kuning, serta daun hijau tua yang mengilap.', 'Karakteristik: Tanaman perdu dengan bunga yang tumbuh bergerombol membentuk rangkaian padat. Bunganya dapat berwarna merah, jingga, merah muda, atau kuning.\r\n\r\nAsal Usul: Asoka yang umum digunakan sebagai tanaman hias (Ixora spp.) berasal dari Asia tropis, terutama kawasan Asia Selatan dan Asia Tenggara.', '', 'Sebagai tanaman hias dan pagar. Bunga dan akarnya secara tradisional digunakan untuk membantu menurunkan tekanan darah dan mengatasi diare ringan.', 'Perlu sinar matahari penuh dan tanah subur. Disiram rutin dan dipangkas setelah berbunga agar tumbuh rimbun.', 'dd0d620a3f03a983.jpg', NULL, '', '2026-10-07 10:47:08'),
(38, 'Kuping gajah', 'Anthurium crystallinum', 'Tanaman Hias', 'Tanaman berdaun besar berbentuk hati seperti telinga gajah, dengan garis putih keperakan yang jelas.', 'Tanaman berdaun besar berbentuk hati seperti telinga gajah, dengan garis putih keperakan yang jelas.', 'Karakteristik: Tanaman herba dengan daun besar berbentuk hati dan permukaan mengilap. Tulang daun terlihat jelas dan memberikan bentuk yang menyerupai telinga gajah.\r\n\r\nAsal Usul: Kuping gajah (Anthurium andraeanum) berasal dari Kolombia hingga Ekuador', '', 'Sebagai tanaman hias dalam ruangan yang menarik dan membuat ruangan terasa lebih segar.', 'Suka cahaya terang yang tidak langsung dan udara lembap. Hindari sinar matahari langsung. Gunakan media yang gembur dan lembap.', 'd2cf3d83d0165d75.jpg', NULL, '', '2026-10-07 10:47:08'),
(39, 'Wali Songo', 'Schefflera arboricola', 'Tanaman Hias', 'Tanaman perdu dengan daun menjari berjumlah 7–9 helai, berwarna hijau mengilap, dan tumbuh rimbun.', 'Tanaman perdu dengan daun menjari berjumlah 7–9 helai, berwarna hijau mengilap, dan tumbuh rimbun.', 'Karakteristik: Tanaman perdu dengan daun majemuk yang terdiri dari beberapa anak daun dan tersusun menjari. Bentuknya rimbun dan cocok digunakan sebagai tanaman hias dalam maupun luar ruangan.\r\n\r\nAsal Usul: Wali Songo (Schefflera arboricola) berasal dari Taiwan dan wilayah Hainan, Tiongkok, kemudian banyak dibudidayakan sebagai tanaman hias.', '', 'Sebagai tanaman hias pot dan pagar. Tahan di tempat teduh dan membantu menyegarkan udara.', 'Suka tempat terang sampai agak teduh dengan tanah gembur. Disiram 2 kali seminggu. Mudah ditanam dari potongan batang.', '1e82190e5f85ca6c.jpg', NULL, '', '2026-10-07 10:47:08'),
(40, 'Ketapang kencana', 'Terminalia mantaly', 'Tanaman Hias', 'Pohon berbentuk payung bertingkat dengan daun bulat yang mengelompok di ujung cabang.', 'Pohon berbentuk payung bertingkat dengan daun bulat yang mengelompok di ujung cabang.', 'Karakteristik: Pohon dengan percabangan yang melebar dan bertingkat. Daunnya kecil, berbentuk oval, dan tumbuh cukup rapat sehingga membentuk tajuk yang rindang.\r\n\r\nAsal Usul: Ketapang kencana (Terminalia mantaly) berasal dari Madagaskar dan kemudian banyak ditanam sebagai pohon peneduh di daerah tropis.', '', 'Sebagai pohon peneduh di jalan, taman, dan halaman. Bentuk tajuknya yang bertingkat sangat menarik.', 'Perlu sinar matahari penuh dan tanah yang tidak tergenang. Disiram secara rutin saat masih muda dan dipangkas untuk membentuk tajuk.', '3a14f87c7813b1aa.jpg', NULL, '', '2026-10-07 10:47:08'),
(41, 'Patah tulang daun keriting', 'Pedilanthus tithymaloides', 'Tanaman Hias', 'Tanaman perdu dengan batang berbelok-belok dan daun hijau yang bergelombang.', 'Tanaman perdu dengan batang berbelok-belok dan daun hijau yang bergelombang. Getahnya putih dan dapat membuat kulit perih.', 'Karakteristik: Tanaman bercabang dengan batang yang berwarna hijau dan mengandung getah putih. Pada varietas atau bentuk berdaun keriting, daun tumbuh kecil dan memiliki bentuk bergelombang atau berpilin.\r\n\r\nAsal Usul: Jika yang kamu maksud adalah bentuk keriting dari Euphorbia tithymaloides, tanaman ini berasal dari Florida, Meksiko hingga wilayah Amerika tropis.', '', 'Sebagai tanaman hias pot yang unik. Getahnya beracun, sehingga harus dijauhkan dari anak-anak dan hewan peliharaan.', 'Cocok di tempat terang sampai setengah teduh dengan tanah berpasir. Cukup disiram sedikit. Gunakan sarung tangan saat memangkas.', 'de1461beb4961228.jpg', NULL, '', '2026-10-07 10:47:08'),
(42, 'Bunga Kasandra', 'Lantana camara', 'Tanaman Hias', 'Tanaman perdu dengan bunga bergerombol warna-warni, seperti merah, jingga, kuning, dan ungu, yang berubah warna seiring waktu.', 'Tanaman perdu dengan bunga bergerombol warna-warni, seperti merah, jingga, kuning, dan ungu, yang berubah warna seiring waktu.', 'Karakteristik: Nama “Kasandra” merupakan nama lokal yang dapat digunakan untuk tanaman yang berbeda di beberapa daerah. Karena itu karakteristiknya perlu disesuaikan dengan jenis tanaman yang kamu punya.\r\n\r\nAsal Usul: Belum bisa dipastikan hanya dari nama lokal “Kasandra”. Kirim foto Bunga Kasandra-nya supaya aku bisa identifikasi dan kasih asal usul yang tepat.', '', 'Sebagai tanaman hias yang menarik kupu-kupu dan lebah. Daun dan buahnya beracun jika dimakan.', 'Perlu sinar matahari penuh dan tahan kering. Dapat tumbuh di berbagai jenis tanah. Dipangkas rutin agar banyak berbunga.', '00f190ec239f883d.jpg', NULL, '', '2026-10-07 10:47:08'),
(43, 'Pepaya', 'Carica papaya', 'Tanaman Sayur / Buah', 'Pohon dengan batang tunggal yang tidak berkayu dan daun besar menjari.', 'Pohon dengan batang tunggal yang tidak berkayu dan daun besar menjari. Buahnya berdaging oranye atau merah.', 'Karakteristik: Tanaman berupa pohon kecil dengan batang tunggal yang lunak. Daunnya besar dan menjari, sedangkan buahnya berbentuk lonjong hingga bulat dengan daging berwarna kuning atau jingga ketika matang.\r\n\r\nAsal Usul: Pepaya (Carica papaya) berasal dari Amerika tropis, terutama wilayah Meksiko selatan hingga Amerika Tengah, kemudian menyebar ke seluruh daerah tropis.', '', 'Buahnya kaya vitamin A dan C serta membantu pencernaan dan melancarkan buang air besar. Daun dan bunganya dapat dimasak sebagai sayur.', 'Perlu sinar matahari penuh dan tanah subur yang gembur. Disiram teratur tanpa menggenang dan dipupuk organik tiap 2–3 bulan. Mulai berbuah pada umur 8–12 bulan.', '3d9883bf803e09fb.jpg', NULL, '', '2026-10-07 10:47:08'),
(44, 'Cabe rawit', 'Capsicum frutescens', 'Tanaman Sayur / Buah', 'Tanaman perdu kecil setinggi 0,5–1,5 m dengan buah kecil yang sangat pedas, hijau saat muda dan merah saat matang.', 'Tanaman perdu kecil setinggi 0,5–1,5 m dengan buah kecil yang sangat pedas, hijau saat muda dan merah saat matang.', 'Karakteristik: Tanaman perdu kecil dengan batang bercabang. Daunnya berbentuk oval dan buahnya berukuran kecil dengan rasa pedas. Buah dapat berwarna hijau dan berubah menjadi merah ketika matang.\r\n\r\nAsal Usul: Cabe rawit (Capsicum frutescens) berasal dari Meksiko selatan hingga Amerika tropis dan kemudian menyebar ke berbagai wilayah dunia, termasuk Indonesia.', '', 'Digunakan sebagai bumbu pedas masakan. Rasa pedasnya menghangatkan badan dan menambah nafsu makan, serta kaya vitamin C.', 'Perlu sinar matahari penuh dan tanah gembur yang banyak bahan organik. Disiram pagi atau sore dan dipupuk berkala agar berbuah lebat.', '3cc1a5c96474ff4f.jpg', NULL, '', '2026-10-07 10:47:08'),
(45, 'Cabe hijau', 'Capsicum annuum', 'Tanaman Sayur / Buah', 'Tanaman perdu dengan buah panjang yang berwarna hijau saat muda.', 'Tanaman perdu dengan buah panjang yang berwarna hijau saat muda. Rasa pedasnya ringan sampai sedang.', 'Karakteristik: Tanaman perdu dengan daun hijau berbentuk oval. Buahnya memanjang atau agak kerucut dan berwarna hijau ketika belum matang, dengan rasa yang dapat berkisar dari sedang hingga sangat pedas tergantung varietas.\r\n\r\nAsal Usul: Cabe hijau umumnya merupakan buah muda dari berbagai jenis Capsicum, termasuk Capsicum annuum. Kelompok cabai ini berasal dari Amerika, kemudian menyebar ke berbagai wilayah dunia.', '', 'Digunakan sebagai sayuran dan bumbu masakan. Sumber vitamin C dan membantu menjaga daya tahan tubuh.', 'Perlu sinar matahari penuh dan tanah subur yang lembap tetapi tidak tergenang. Ditanam dari biji dan dapat dipanen pada umur 3–4 bulan.', '6e3b7061f0afc1a3.jpg', NULL, '', '2026-10-07 10:47:08'),
(46, 'Jagung', 'Zea mays', 'Tanaman Sayur / Buah', 'Tanaman setahun seperti rumput, tingginya 1,5–3 m.', 'Tanaman setahun seperti rumput, tingginya 1,5–3 m. Tongkolnya berisi biji kuning atau putih yang terbungkus kulit.', 'Karakteristik: Tanaman rumput berbatang tegak dengan daun panjang dan lebar. Tanaman menghasilkan tongkol yang berisi biji-biji jagung dalam barisan.\r\n\r\nAsal Usul: Jagung (Zea mays) berasal dari Mesoamerika, terutama wilayah Meksiko, dan kemudian menyebar ke seluruh dunia.', '', 'Sumber karbohidrat dan serat, dapat menjadi makanan pokok pengganti nasi, serta bahan pakan ternak dan tepung maizena.', 'Perlu sinar matahari penuh, tanah subur dan gembur, serta air yang cukup. Jarak tanam sekitar 70 × 25 cm. Jagung manis dapat dipanen pada umur 70–85 hari.', '6580dc9f15311f3f.jpg', NULL, '', '2026-10-07 10:47:08'),
(47, 'Mangga', 'Mangifera indica', 'Tanaman Sayur / Buah', 'Pohon besar rindang berdaun lonjong, buah berdaging manis atau asam tergantung varietas.', 'Pohon besar rindang berdaun lonjong, buah berdaging manis atau asam tergantung varietas.', 'Karakteristik: Pohon berukuran sedang hingga besar dengan daun panjang, tebal, dan berwarna hijau. Buahnya memiliki berbagai bentuk dan warna, dengan daging yang umumnya manis dan beraroma khas ketika matang.\r\n\r\nAsal Usul: Mangga (Mangifera indica) berasal dari Asia Selatan, terutama wilayah India dan sekitarnya, kemudian menyebar luas ke Asia Tenggara dan berbagai daerah tropis.', '', 'Buah kaya vitamin A, C, dan serat; dimakan segar, jus, rujak, asinan; pohon juga sebagai peneduh.', 'Matahari penuh, tanah dalam dan drainase baik, siram saat muda. Pangkas pemeliharaan; berbuah umur 3–5 tahun (cangkok/okulasi).', 'd6641fcacd3f0cd9.jpg', NULL, '', '2026-10-07 10:47:08'),
(48, 'Terong', 'Solanum melongena', 'Tanaman Sayur / Buah', 'Semak tegak setinggi 60–100 cm, bunga ungu, buah memanjang atau bulat berwarna ungu/hijau/putih.', 'Semak tegak setinggi 60–100 cm, bunga ungu, buah memanjang atau bulat berwarna ungu/hijau/putih.', 'Karakteristik: Tanaman perdu dengan batang bercabang dan daun lebar yang memiliki permukaan agak berbulu. Buahnya dapat berbentuk lonjong atau bulat dan memiliki warna yang beragam, seperti ungu, hijau, putih, atau hitam.\r\n\r\nAsal Usul: Terong (Solanum melongena) berasal dari Asia, dengan sejarah domestikasi yang berkaitan dengan wilayah India dan Asia Tenggara, kemudian menyebar ke berbagai belahan dunia.', '', 'Sayuran rendah kalori kaya serat dan antosianin; membantu menjaga kolesterol dan kesehatan jantung.', 'Matahari penuh, tanah gembur banyak humus, siram rutin. Panen 70–90 hari setelah tanam.', '8a22807719ec4ec4.webp', NULL, '', '2026-10-07 10:47:08');

